def transect(world, x1, y1, x2, y2):
    world.index(x1,y1)
    world.index(x2,y2)
    dx, dy = abs(x2-x1), -abs(y2-y1)
    sx, sy = (1 if x1 < x2 else -1), (1 if y1 < y2 else -1)
    error = dx+dy
    result = []
    while True:
        result.append({"x": x1, "y": y1, **world.cell(x1,y1).to_dict()})
        if (x1,y1) == (x2,y2):
            break
        double = 2*error
        if double >= dy:
            error += dy
            x1 += sx
        if double <= dx:
            error += dx
            y1 += sy
    return result


